//! The AP242 EXPRESS schema as data: entity and type declarations, Part 21 instance and
//! document validation, and the *family* of every entity type.
//!
//! The tables in `express_table.rs` are generated by `tools/express_table.py` from the AP242
//! MIM long forms (stepcode's copies; source URL and sha256 in each [`Edition`]):
//!
//! - [`AP242_ED4`], WG12 N11521: **AP242 edition 4** (ISO 10303-242:2025), `FILE_SCHEMA`
//!   `{ 1 0 10303 442 7 1 4 }`. Its 2407 entity types are exactly the AP242 edition 4 list of
//!   NIST's STEP File Analyzer (`sfa-data.tcl`, `ap242e4`), which also identifies edition 4 by
//!   version 7 of the object identifier (`sfa-gen.tcl`); 274 of them are not in its edition 3
//!   list (e.g. the `a3m_data_quality_*` entities). Its header says 2,404 entities; the file
//!   declares 2407.
//! - [`AP242_ED1`], WG12 N8324 (2014): **AP242 edition 1**, `{ 1 0 10303 442 1 1 4 }`, whose
//!   1726 entity types equal the analyzer's edition 1 list.
//!
//! No long form of edition 2 (`{… 442 3 1 4}`, 2020) or edition 3 (`{… 442 4 1 4}`, 2022) was
//! found (stepcode's history holds only these two; SC4's module repositories publish short
//! forms only), so files of those editions have no table of their own: they are checked as
//! an upgrade to the target.
//!
//! The writer targets exactly [`TARGET_SCHEMA`], edition 4.
//!
//! [`Edition::validate`] checks one Part 21 record: declared and instantiable entity names; the
//! attribute count; INTEGER, REAL, NUMBER, STRING, BOOLEAN, LOGICAL and BINARY kinds;
//! enumeration values; `$` only where OPTIONAL and `*` only where an inherited attribute is
//! redeclared as derived; aggregates with their bounds and element types; reference targets
//! whose types satisfy the attribute's entity or SELECT type; SELECT values of defined types
//! written as typed parameters (an untyped `0.075` as `measure_with_unit.value_component` is a
//! violation); complex instances with parts in alphabetical order, every supertype present,
//! each part's own attributes, a combination the SUPERTYPE expressions allow, and the internal
//! mapping when the set is the supertype closure of one entity type. WHERE and UNIQUE rules are
//! not evaluated; [`Edition::rules`] names them for citation. Not checked either: UNIQUE
//! aggregate elements, STRING and BINARY widths, and aggregate bounds that are expressions.

use std::collections::{BTreeSet, HashMap, HashSet};

use step_io::parser::{Attribute as Param, Graph, RawEntity};

#[rustfmt::skip]
#[path = "express_table.rs"]
mod table;

pub use table::{AP242_ED1, AP242_ED4};

/// The `FILE_SCHEMA` of the edition the writer targets: AP242 edition 4.
pub const TARGET_SCHEMA: &str =
    "AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF { 1 0 10303 442 7 1 4 }";

/// The edition the writer targets ([`TARGET_SCHEMA`]).
pub static TARGET: &Edition = &AP242_ED4;

/// Every edition with a table, oldest first.
pub static EDITIONS: [&Edition; 2] = [&AP242_ED1, &AP242_ED4];

/// One edition's schema.
#[derive(Debug)]
pub struct Edition {
    /// The `FILE_SCHEMA` identifier of the edition.
    pub file_schema: &'static str,
    pub source_url: &'static str,
    pub source_sha256: &'static str,
    /// Sorted by name.
    pub types: &'static [TypeDecl],
    /// Sorted by name.
    pub entities: &'static [EntityDecl],
}

/// A TYPE declaration (names lower case, as all names in the table).
#[derive(Debug)]
pub struct TypeDecl {
    pub name: &'static str,
    pub def: TypeDef,
    /// Labels of its WHERE rules.
    pub rules: &'static [&'static str],
}

#[derive(Debug)]
pub enum TypeDef {
    /// Member type names, sorted.
    Select(&'static [&'static str]),
    Enumeration(&'static [&'static str]),
    Defined(Ty),
}

/// An attribute or element type.
#[derive(Debug, Clone, Copy)]
pub enum Ty {
    Integer,
    Real,
    Number,
    String,
    Boolean,
    Logical,
    Binary,
    /// An entity or a defined type.
    Named(&'static str),
    Aggregate(&'static Aggregate),
}

#[derive(Debug)]
pub struct Aggregate {
    pub kind: AggregateKind,
    /// `None` when the bound is not a literal (an expression); not checked then.
    pub lower: Option<u32>,
    /// `None` for `?` or a bound that is not a literal.
    pub upper: Option<u32>,
    /// `ARRAY … OF OPTIONAL`: elements may be `$`.
    pub optional: bool,
    pub unique: bool,
    pub of: Ty,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AggregateKind {
    List,
    Set,
    Bag,
    Array,
}

/// An ENTITY declaration.
#[derive(Debug)]
pub struct EntityDecl {
    pub name: &'static str,
    pub is_abstract: bool,
    /// SUBTYPE OF, in declared order.
    pub supertypes: &'static [&'static str],
    /// SUPERTYPE OF.
    pub supertype_of: Option<Sx>,
    /// Its own explicit attributes, in declared order.
    pub attributes: &'static [Attribute],
    /// Inherited attributes it redeclares (`SELF\e.a`), by the entity that declares them.
    pub redeclared: &'static [Redeclared],
    /// Labels of its UNIQUE and WHERE rules, in declared order.
    pub rules: &'static [&'static str],
}

/// A supertype expression.
#[derive(Debug)]
pub enum Sx {
    Entity(&'static str),
    OneOf(&'static [Sx]),
    AndOr(&'static [Sx]),
    And(&'static [Sx]),
}

#[derive(Debug)]
pub struct Attribute {
    pub name: &'static str,
    pub optional: bool,
    pub ty: Ty,
}

/// An inherited explicit attribute redeclared in a subtype: with a narrower type, or (`derived`)
/// as a derived attribute, written `*` in Part 21.
#[derive(Debug)]
pub struct Redeclared {
    /// The entity declaring the attribute.
    pub entity: &'static str,
    pub attribute: &'static str,
    pub derived: bool,
    pub optional: bool,
    pub ty: Ty,
}

/// An explicit attribute as an instance writes it: its declaration and the redeclarations that
/// apply to the instance's type.
#[derive(Debug, Clone)]
pub struct Slot {
    /// The entity declaring it.
    pub entity: &'static str,
    pub name: &'static str,
    /// OPTIONAL in its declaration and in every redeclaration that applies.
    pub optional: bool,
    /// Redeclared as derived: written `*`.
    pub derived: bool,
    pub ty: Ty,
    /// The types of explicit redeclarations that apply; a value satisfies each.
    pub redeclared: Vec<Ty>,
}

/// The family of an entity type: what a PMI edit does with an instance of it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Family {
    SemanticPmi,
    Presentation,
    ValidationProperty,
    Other,
}

impl Family {
    pub fn as_str(self) -> &'static str {
        match self {
            Family::SemanticPmi => "semantic-pmi",
            Family::Presentation => "presentation",
            Family::ValidationProperty => "validation-property",
            Family::Other => "other",
        }
    }
}

/// The family rules, in order: an entity type takes the family of the first root it is (a
/// subtype of); otherwise [`Family::Other`]. Order matters where roots nest:
/// `draughting_model_item_association` is an `item_identified_representation_usage`, and
/// `annotation_occurrence` a `styled_item`.
///
/// - Semantic PMI: shape aspects (datums, datum features and targets, datum systems and their
///   compartments and elements, tolerance zones, groups) and their relationships (dimensional
///   locations, datum establishment and target features, derivation); dimensional sizes and
///   their representation; geometric tolerances and their relationships and classifications;
///   zones, plus/minus tolerances, tolerance values, limits and fits, default tolerance tables;
///   datum references and modifiers with values; threads and knurls (not other
///   `feature_definition`s); the usages binding shape aspects to faces
///   (`item_identified_representation_usage`, PMI practice §5.1); the value qualifiers of
///   §5.2.2 and §5.4 (`type_qualifier`, `value_format_type_qualifier`,
///   `measure_qualification`); user defined attributes (`general_property` and its association,
///   UDA practice §5; that a `general_property` is a UDA is stated by its name
///   'user defined attribute').
